$(function(){$(".counters").length>0&&fetch("https://pediatrasencasa.github.io/cdn/data/statistics.json").catch(n=>console.error(n)).then(n=>n.json()).then(n=>{const t=n[0];console.log(t);var i={useEasing:!0,useGrouping:!0,separator:",",decimal:".",prefix:"",suffix:""};$(".counters").waypoint(function(){var f=new CountUp("counting-1",0,t.diagnostics,0,6.5,i),n,r,u;f.start();n=new CountUp("counting-2",0,t.clients,0,6.5,i);n.start();r=new CountUp("counting-3",0,t.beneficiaries,0,6.5,i);r.start();u=new CountUp("counting-4",0,t.consults,0,6.5,i);u.start()},{offset:"100%"})})});